pub(crate) fn unescape_attribute_utf8<'a>(
    attribute: &quick_xml::events::attributes::Attribute<'a>,
) -> quick_xml::Result<Cow<'a, str>> {
    use quick_xml::encoding::EncodingError;
    use std::str::from_utf8;

    let decoded = match &attribute.value {
        Cow::Borrowed(bytes) => Cow::Borrowed(from_utf8(bytes).map_err(EncodingError::Utf8)?),
        Cow::Owned(bytes) => Cow::Owned(from_utf8(bytes).map_err(EncodingError::Utf8)?.to_owned()),
    };
    unescape_decoded_attribute(decoded)
}

pub(crate) fn decode_unescape_attribute<'a>(
    attribute: &quick_xml::events::attributes::Attribute<'a>,
    decoder: Decoder,
) -> quick_xml::Result<Cow<'a, str>> {
    let decoded = match &attribute.value {
        Cow::Borrowed(bytes) => decoder.decode(bytes)?,
        Cow::Owned(bytes) => Cow::Owned(decoder.decode(bytes)?.into_owned()),
    };
    unescape_decoded_attribute(decoded)
}

fn unescape_decoded_attribute<'a>(decoded: Cow<'a, str>) -> quick_xml::Result<Cow<'a, str>> {
    match quick_xml::escape::unescape(&decoded)? {
        Cow::Borrowed(_) => Ok(decoded),
        Cow::Owned(value) => Ok(Cow::Owned(value)),
    }
}

