#[test]
fn utf8_attributes_preserve_legacy_unescape_semantics() {
    assert_eq!(attribute_value(r#"<x v="R&amp;D&#xE9;"/>"#, b"v"), "R&Dé");
    assert_eq!(
        attribute_value("<x v=\"a\tb\nc\rd&#9;&#10;&#13;\"/>", b"v"),
        "a\tb\nc\rd\t\n\r"
    );
    assert_eq!(
        attribute_value("<x xmlns:r=\"urn:test\" r:id=\"r&amp;é\"/>", b"r:id"),
        "r&é"
    );
}

