#[test]
fn decoder_aware_attributes_preserve_non_utf8_values() {
    let xml = b"<?xml version=\"1.0\" encoding=\"windows-1252\"?><x v=\"caf\xe9&amp;&#x9;\"/>";
    let mut reader = quick_xml::Reader::from_reader(&xml[..]);
    let mut buffer = Vec::new();
    reader.read_event_into(&mut buffer).unwrap();
    buffer.clear();
    let decoder = reader.decoder();
    let quick_xml::events::Event::Empty(element) = reader.read_event_into(&mut buffer).unwrap() else {
        panic!("expected empty element");
    };
    let attribute = element.attributes().next().unwrap().unwrap();
    assert_eq!(
        decode_unescape_attribute(&attribute, decoder).unwrap(),
        "café&\t"
    );
}

