fn cow() {
    let mut reader = quick_xml::Reader::from_str(r#"<x v="plain"/>"#);
    let quick_xml::events::Event::Empty(element) = reader.read_event().unwrap() else { panic!() };
    let attribute = element.attributes().next().unwrap().unwrap();
    assert!(matches!(unescape_attribute_utf8(&attribute), Ok(Cow::Borrowed("plain"))));
    let mut reader = quick_xml::Reader::from_str(r#"<x v="&unknown;"/>"#);
    let quick_xml::events::Event::Empty(element) = reader.read_event().unwrap() else { panic!() };
    assert!(unescape_attribute_utf8(&element.attributes().next().unwrap().unwrap()).is_err());
}

